INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('festive-specials', 'Festive Specials', '节日限定菜单', '节日限定', 'Limited-time seasonal crepes, snacks and drinks crafted for holidays and celebrations — available while ingredients last.', '逢年过节特别推出的限定风味煎饼、点心与特调，限时供应、售完即止。', 0);

INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('savoury-crepes', 'Savoury Jian Bing', '招牌咸味煎饼', '咸味煎饼', 'Freshly griddled to order with natural fruit-and-veg batter, cracked egg, a crisp wonton centre and Mrs Liu''s savoury house sauce.', '鲜榨果蔬面糊上热铁板手工现摊，磕蛋刷自家慢熬咸香酱、夹上酥脆薄脆与丰富配料，趁热折好装袋。', 1);
INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('roast-duck-crepe', 'savoury-crepes', 'Roast Duck Jian Bing', '招牌烤鸭煎饼', '烤鸭卷饼煎饼', 'Crisp-skinned roast duck carved warm onto a freshly griddled natural-batter crepe with crunchy veg, spring onions and Mrs Liu''s savoury sauce.', '皮酥肉嫩的现切烤鸭铺满果蔬饼皮，配上脆生菜、香葱丝与自家咸香酱，满满一口特别香。', '/images/roast-duck-jianbing.webp', 'Sliced golden roast duck laid generously across a fresh green vegetable-batter Jian Bing crepe', '翠绿果蔬煎饼皮上铺满现切片的金黄脆皮烤鸭', '[]', NULL, NULL, 1, 1, 0);
