INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('beef-crepe', 'savoury-crepes', 'Beef Jian Bing', '招牌牛肉煎饼', '牛肉煎饼', 'Tender Halal beef folded into a hot, crisp crepe with egg, fresh lettuce, spring onions, crunchy shallots and our savoury house sauce. Properly filling.', '热乎脆香的果蔬饼皮，裹满鲜嫩清真牛肉、鲜蛋、脆生菜、香葱和酥脆炸洋葱，刷上自家咸香酱，拿在手里沉甸甸的。', '/images/beef-jianbing-stack.webp', 'Generously stacked Beef Jian Bing sliced in half beneath the branded Jian Bing Liu kraft sleeve', '印有煎饼刘与爱民朱印的牛皮纸袋下方，对半切开叠放的满馅招牌牛肉煎饼', '["halal"]', NULL, NULL, 1, 1, 1);
