INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('jerk-chicken-crepe', 'savoury-crepes', 'Caribbean Jerk Chicken Jian Bing', '加勒比牙买加烤鸡煎饼', '加勒比牙买加烤鸡煎饼', 'A true Camden Road collaboration — smoky spiced Caribbean jerk chicken folded hot into our natural dragon-fruit & spinach Jian Bing.', '卡姆登路限定融合口味——烟熏微辣的加勒比烤鸡夹进鲜榨果蔬煎饼里，肉香与饼香碰撞得意外合拍。', '/images/dragonfruit-pink-jianbing.webp', 'Naturally pink dragon-fruit batter Jian Bing generously filled with grilled chicken and crisp salad', '红心火龙果粉色果蔬皮煎饼，夹满厚实烤鸡肉与鲜脆时蔬', '[]', NULL, NULL, 0, 1, 5);
