INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('tuna-crepe', 'savoury-crepes', 'Tuna Jian Bing (Medium)', '吞拿鱼煎饼（中）', '吞拿鱼煎饼（中）', 'A lighter medium crepe filled with savoury tuna, crisp greens and egg — quick and easy for lunch on the go.', '分量轻盈的中份煎饼，鲜香吞拿鱼配脆生菜与鲜蛋，适合午间随手带走。', '/images/chicken-crepe-sleeve.webp', 'Warm medium Jian Bing folded neatly into a brown takeaway sleeve', '热气腾腾装在牛皮纸袋里的中份煎饼', '[]', NULL, NULL, 0, 1, 6);
