INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('veggie-lover-crepe', 'savoury-crepes', 'Veggie Lover Jian Bing', '素菜煎饼', '素菜煎饼', 'Crunchy shredded potato, cool cucumber, fresh spinach, lettuce and fried shallots tucked inside a natural fruit-and-veg crepe with savoury house sauce.', '爽脆土豆丝、清口黄瓜条、嫩菠菜、生菜与酥香炸洋葱，卷进鲜榨果蔬饼皮里刷上咸香酱，清爽又管饱。', '/images/veggie-crepe-griddle.webp', 'Colourful fruit-and-vegetable batter Veggie Lover Jian Bing topped with fresh greens on the griddle', '铁板上刚摊好的彩色果蔬面糊素菜煎饼，铺满翠绿蔬菜与香葱', '["vegetarian"]', NULL, NULL, 1, 1, 7);
