INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('spinach-cheese-crepe', 'savoury-crepes', 'Spinach & Cheese Jian Bing', '菠菜芝士煎饼', '菠菜芝士煎饼', 'Fresh spinach, egg and melted cheese folded warm into a crisp crepe with a light brush of house sauce — simple and cosy.', '鲜嫩菠菜、鸡蛋加上热乎融化的香浓芝士，轻刷一层自家酱，简单踏实又暖心。', '/images/folded-rainbow-crepe.webp', 'Freshly folded vegetable-batter crepe sizzling on the hot griddle', '铁板上正在折叠的彩色果蔬面糊煎饼', '["vegetarian"]', NULL, NULL, 0, 1, 8);
