INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('flourless-crepe', 'savoury-crepes', 'Flourless Jian Bing', '无面煎饼', '无面煎饼', 'A lighter, flour-free egg wrap cooked crisp on the griddle and loaded with fresh greens and savoury fillings.', '不加面粉的轻盈纯蛋皮现摊煎饼，依然铺满鲜脆时蔬与秘制酱香，低碳水也能放心解馋。', '/images/golden-jianbing-cut.webp', 'Golden sesame-crusted Jian Bing sliced open to reveal fresh greens and savoury layers', '金黄撒芝麻的现摊煎饼切面，露出翠绿蔬菜与扎实内馅', '[]', NULL, NULL, 0, 1, 9);
