INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('sweet-crepes-and-desserts', 'Sweet Crepes', '花式可丽饼 · 甜煎饼', '花式可丽饼', 'Caramelised crème brûlée cones, matcha & pistachio fluff crepes, fresh strawberry cones and warm chocolate crepes.', '现烤焦糖布蕾甜筒、抹茶开心果可丽饼、小动物鲜草莓可丽饼与热乎巧克力甜煎饼。', 2);
INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('creme-brulee-crepe', 'sweet-crepes-and-desserts', 'Crème Brûlée & Mascarpone Crepe (Limited Edition)', '焦糖布蕾蛋糕可丽饼', '焦糖布蕾蛋糕可丽饼', 'Silky custard cream and mascarpone torched to a crackly golden caramel top, ringed with fresh strawberries inside a warm hand-rolled crepe cone.', '丝滑马斯卡彭奶油布蕾现烤出咔嚓焦糖脆壳，围满新鲜红草莓和脆卷，奶香浓郁甜而不腻。', '/images/creme-brulee-crepe.webp', 'Caramelised Crème Brûlée custard sweet crepe cone ringed with fresh strawberries and chocolate wafer rolls', '围满新鲜草莓与巧克力脆卷的现烤焦糖布蕾蛋糕可丽饼', '["vegetarian"]', NULL, NULL, 1, 1, 0);
