INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('matcha-pistachio-crepe', 'sweet-crepes-and-desserts', 'Matcha & Pistachio Crème Brûlée Crepe', '抹茶开心果布蕾蛋糕可丽饼', '抹茶开心果布蕾蛋糕可丽饼', 'Fragrant green tea matcha crepe layered with creamy brûlée custard, nutty pistachio fluff and a dusting of rich matcha.', '茶香清苦回甘的抹茶饼皮，层层叠入绵密布蕾蛋糕与香浓开心果奶油脆，口感丰富不甜腻。', '/images/matcha-pistachio-crepe.webp', 'Green tea matcha crepe cone topped with generous matcha pistachio crumble and a cute bunny sweet', '铺满细腻抹茶粉与开心果碎、点缀可爱小兔的抹茶开心果可丽饼', '["vegetarian"]', NULL, NULL, 1, 1, 1);
