INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('banana-crepe', 'sweet-crepes-and-desserts', 'Banana Sweet Crepe (Cute Character Edition)', '香蕉可丽饼（小动物）', '香蕉可丽饼（小动物）', 'Sweet sliced banana, whipped cream, chocolate drizzle and cute character toppings wrapped warm to order.', '香甜现切香蕉片配绵密奶油、巧克力酱和萌趣小动物点缀，趁热吃软糯香甜。', '/images/nutella-strawberry-crepe.webp', 'Warm folded sweet crepe topped with sliced banana, fresh strawberries, cream and chocolate drizzle', '铺满香蕉片、鲜草莓、奶油与巧克力酱的现摊甜煎饼', '["vegetarian"]', NULL, NULL, 0, 1, 3);
