INSERT OR IGNORE INTO menu_items (id, category_id, name_en, name_zh, chinese_name, desc_en, desc_zh, image_url, image_alt_en, image_alt_zh, dietary_tags, note_en, note_zh, is_featured, is_available, sort_order) VALUES ('chocolate-crepe', 'sweet-crepes-and-desserts', 'Warm Chocolate Crepe', '巧克力可丽饼', '巧克力可丽饼', 'A warm, soft crepe generously spread with rich chocolate — simple, cosy and freshly griddled for a fiver.', '刚出锅的软韧甜饼皮，厚厚抹上一层融化的香浓巧克力酱，简单解馋又暖心。', '/images/chocolate-strawberry-triangle.webp', 'Warm triangle-folded chocolate dessert crepe drizzled with rich chocolate sauce', '淋满浓香巧克力酱的三角折叠热乎巧克力可丽饼', '["vegetarian"]', NULL, NULL, 0, 1, 4);
