INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('meal-deals', 'Meal Deals', '超值优惠套餐', '优惠套餐', 'Pair our signature savoury Jian Bing with Hong Kong Iced Lemon Tea or Freshly Ground Soya Milk and save.', '招牌咸味煎饼搭配港式冻柠茶或现磨豆浆，热饼配好饮，一顿刚好更划算。', 3);
