INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('mains-and-rice', 'Homestyle Mains & Rice', '家常主食盖饭', '家常主食', 'Slow-simmered comfort bowls from Mrs Liu''s kitchen, served piping hot over fluffy steamed white rice.', '像家里灶台上慢火炖出的热乎硬菜，浓汤拌着热腾腾的白米饭吃格外踏实。', 4);
