INSERT OR IGNORE INTO menu_categories (id, title_en, title_zh, chinese_title, subtitle_en, subtitle_zh, sort_order) VALUES ('snacks-and-dumplings', 'Chinese Snacks, Dumplings & Soups', '中式小吃 · 煎饺 · 鲜汤', '街头小吃', 'Crispy Chinese Roujiamo (Halal beef or braised pork), pan-fried dumplings, Halal beef buns and flatbreads, handmade wontons and slow-simmered soups.', '酥脆肉夹馍（清真牛肉/老卤猪肉）、脆底煎饺、清真牛肉大包与馅饼、手工鲜汤馄饨与现熬养生鸡汤，单点或加配都合适。', 5);
